import React, { useEffect, useRef, useState } from 'react';
import { Badge, Button, Card, Spinner } from 'react-bootstrap';
import ModelViewBox from '../../../components/Atom/ModelViewBox';
import FormLayout from '../../../utils/formLayout';
import { employeeFormContainer } from './formFieldData';
import Table from '../../../components/Table';
import { findArrObj, showConfirmationDialog, showMessage } from '../../../utils/AllFunction';
import { getSettingsRequest, resetUpdateSettings, resetGetSettings, updateSettingsRequest } from '../../../redux/actions';
import { usePageTitle, useRedux } from '../../../hooks';
import { NotificationContainer } from 'react-notifications';
import moment from 'moment';
import { createUploadImagesRequest } from '../../../redux/uploads/actions';
import { baseURL } from '../../../api/ApiConfig';

let isEdit = false;

function Index() {

    usePageTitle({
        title: 'E-mark',
        breadCrumbItems: [
            {
                path: '/e-mark/home',
                label: 'E-mark',
            },
            {
                path: '/e-mark/enterprise-information',
                label: 'Enterprise Information',
                active: true,
            },
        ],
    });


    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0].pagePermission, 'label', "Setting");
    const accessIds = (pageAccessData?.[0]?.children?.[0]?.access || '').split(',').map(id => id.trim()); // for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId;

    const { dispatch, appSelector } = useRedux();

    const { getSettingsSuccess, getSettingsList, getSettingsFailure,
        updateSettingsSuccess, updateSettingsData, updateSettingsFailure, errorMessage,

    } = appSelector((state) => ({

        getSettingsSuccess: state.settingsReducer.getSettingsSuccess,
        getSettingsList: state.settingsReducer.getSettingsList,
        getSettingsFailure: state.settingsReducer.getSettingsFailure,

        updateSettingsSuccess: state.settingsReducer.updateSettingsSuccess,
        updateSettingsData: state.settingsReducer.updateSettingsData,
        updateSettingsFailure: state.settingsReducer.updateSettingsFailure,

        errorMessage: state.settingsReducer.errorMessage,
    }));

    const [state, setState] = useState({});
    const [isLoading, setIsLoading] = useState(false);
    const [errors, setErrors] = useState([]);
    const errorHandle = useRef();

    useEffect(() => {
        setIsLoading(true)
        dispatch(getSettingsRequest());
    }, []);

    useEffect(() => {
        if (getSettingsSuccess) {
            setIsLoading(false)
            setState({
                companyName: getSettingsList[0].companyName || "",
                companyMobile: getSettingsList[0].companyMobile || "",
                companyAltMobile: getSettingsList[0].companyAltMobile || "",
                companyMail: getSettingsList[0].companyMail || "",
                companyAddress: getSettingsList[0].companyAddress || "",
                companyDistrict: getSettingsList[0].companyDistrict || "",
                companyState: getSettingsList[0].companyState || "",
                companyPincode: getSettingsList[0].companyPincode || "",
                companyGstNo: getSettingsList[0].companyGstNo || "",
                companyLogo: getSettingsList[0].companyLogo || "",
                logoPreview: `${baseURL}${getSettingsList[0].companyLogo}` || "",
                updatedAt: getSettingsList[0].updatedAt || null,
            });
            dispatch(resetGetSettings())
        } else if (getSettingsFailure) {
            setIsLoading(false)
            dispatch(resetGetSettings())
        }
    }, [getSettingsSuccess, getSettingsFailure]);

    useEffect(() => {
        if (updateSettingsSuccess) {
            if (Array.isArray(state?.companyLogo)) {
                const formData = new FormData();
                const originalFile = state?.companyLogo[0];
                const renamedFile = new File(
                    [originalFile],
                    `k3-woment-foundation-logo-${originalFile.name}`,
                    {
                        type: originalFile.type,
                        lastModified: originalFile.lastModified,
                    }
                );
                formData.append("companyLogo", renamedFile);
                dispatch(createUploadImagesRequest(formData, 1))
            }
            showMessage('success', 'Updated Successfully');
            dispatch(resetUpdateSettings())
        } else if (updateSettingsFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetUpdateSettings())
        }
    }, [updateSettingsSuccess, updateSettingsFailure]);

    const onFormClear = () => {
        setErrors([]);
        setState({});
    };

    const handleValidation = () => {
        errorHandle.current.validateFormFields();
    }

    const onFormSubmit = async () => {
        const submitRequest = {
            companyName: state?.companyName || "",
            companyMobile: state?.companyMobile || "",
            companyAltMobile: state?.companyAltMobile || "",
            companyMail: state?.companyMail || "",
            companyAddress: state?.companyAddress || "",
            companyDistrict: state?.companyDistrict || "",
            companyState: state?.companyState || "",
            companyPincode: state?.companyPincode || "",
            companyGstNo: state?.companyGstNo || "",
            companyLogo: Array.isArray(state?.companyLogo) ? "" : state?.companyLogo,
        }


        dispatch(updateSettingsRequest(submitRequest, 1))
    };

    const formImage = async (e) => {
        const file = e.target.files[0];
        if (file) {
            const imageURL = URL.createObjectURL(file);
            setState({
                ...state,
                companyLogo: [file],
                logoPreview: imageURL,
            });
        }
    }



    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? <div className='bg-light opacity-0.25'>
                <div className="d-flex justify-content-center m-5">
                    <Spinner className='mt-5 mb-5' animation="border" />
                </div>
            </div> :
                <Card>
                    <Card.Body>
                        {/* <h4 className='mb-4'>Settings</h4> */}
                        <FormLayout
                            dynamicForm={roleIdforRole === 1
                                ? employeeFormContainer
                                : employeeFormContainer.filter(section =>
                                    !section.formFields.some(field =>
                                        field.title === "Autendication" || field.inputType === "button"
                                    )
                                )}
                            handleSubmit={onFormSubmit}
                            setState={setState}
                            state={state}
                            ref={errorHandle}
                            onClickCallBack={{
                                "formUpdate": handleValidation,
                                "onFormClear": onFormClear
                            }}
                            onChangeCallBack={{ "formImage": formImage }}
                            noOfColumns={1}
                            errors={errors}
                            setErrors={setErrors}
                        />

                        <div>{`Last Update on ${moment(state?.updatedAt || null).format('DD-MM-YYYY')}`}</div>
                    </Card.Body>
                </Card>
            }

        </React.Fragment>
    );
}

export default Index;
